/**
 * @param {number[]} nums
 * @return {number}
 */
var minMoves = function(nums) {
    const max = Math.max(...nums);
    let res = 0;

    for (const num of nums) {
        res += max - num;
    }

    return res;
};

/**
 * @param {number[]} nums
 * @return {number}
 */
var minMoves = function(nums) {
    let max = 0;
    let res = 0;

    for (const num of nums) {
        max = Math.max(max, num);
        res += 100 - num;
    }

    return res - (100 - max) * nums.length;
};
